#pragma once
#include <filesystem>
#include <fstream>
namespace boltgun_presentation {
inline void prepare_white_palette(const std::filesystem::path& root) {
    // Authored 1x1 opaque-white PNG, shared by the unlit gauntlets and reticle.
    // Generated bytes contain no game data and use the active UEVR profile only.
    constexpr unsigned char png[]={137,80,78,71,13,10,26,10,0,0,0,13,73,72,68,82,
        0,0,0,1,0,0,0,1,8,6,0,0,0,31,21,196,137,0,0,0,11,73,68,65,84,
        120,156,99,248,15,4,0,9,251,3,253,251,94,107,43,0,0,0,0,73,69,78,68,174,66,96,130};
    const auto filename=root/L"data/hands3d_color.png";
    std::ofstream texture(filename,std::ios::binary|std::ios::trunc);
    if(!texture) return;
    texture.write(reinterpret_cast<const char*>(png),sizeof(png));texture.close();
    if(!texture) return;
    const auto path=filename.generic_u8string();
    if(path.empty()||path.find('\n')!=std::string::npos||path.find('\r')!=std::string::npos) return;
    std::ofstream hint(root/L"data/hands3d.texture_path",std::ios::binary|std::ios::trunc);
    hint.write(path.data(),static_cast<std::streamsize>(path.size()));
}
}
